export type ColumnId = 'todo' | 'doing' | 'done';

export const COLUMN_IDS: ColumnId[] = ['todo', 'doing', 'done'];

export interface Card {
  id: string;
  title: string;
}

export interface BoardState {
  columns: Record<ColumnId, Card[]>;
  /** Latest screen-reader announcement per column (set on the target column of a move). */
  announcements: Record<ColumnId, string>;
}

export type BoardAction =
  | { type: 'ADD_CARD'; column: ColumnId; title: string }
  | { type: 'MOVE_CARD'; id: string; target: ColumnId; targetIndex: number }
  | { type: 'DELETE_CARD'; id: string };

let nextCardId = 1;

export function makeCard(title: string): Card {
  return { id: `card-${nextCardId++}`, title };
}

function emptyColumns(): Record<ColumnId, Card[]> {
  return { todo: [], doing: [], done: [] };
}

function emptyAnnouncements(): Record<ColumnId, string> {
  return { todo: '', doing: '', done: '' };
}

/** Clamp an index into [0, length] so insertion never goes out of bounds. */
export function clampIndex(index: number, length: number): number {
  return Math.max(0, Math.min(index, length));
}

export function initialState(): BoardState {
  return {
    columns: {
      todo: [makeCard('Write spec'), makeCard('Design API')],
      doing: [makeCard('Implement reducer')],
      done: [],
    },
    announcements: emptyAnnouncements(),
  };
}

function locate(state: BoardState, id: string): { column: ColumnId; index: number } | undefined {
  for (const col of COLUMN_IDS) {
    const index = state.columns[col].findIndex((c) => c.id === id);
    if (index !== -1) return { column: col, index };
  }
  return undefined;
}

export function boardReducer(state: BoardState, action: BoardAction): BoardState {
  switch (action.type) {
    case 'ADD_CARD': {
      const card = makeCard(action.title);
      return {
        ...state,
        columns: {
          ...state.columns,
          [action.column]: [...state.columns[action.column], card],
        },
      };
    }

    case 'MOVE_CARD': {
      const location = locate(state, action.id);
      if (!location) return state;

      const { column: source, index: sourceIndex } = location;
      const sourceCards = state.columns[source];
      const card = sourceCards[sourceIndex];

      // Remove from source first...
      const withoutCard = [
        ...sourceCards.slice(0, sourceIndex),
        ...sourceCards.slice(sourceIndex + 1),
      ];

      // ...then fix up the insertion index when moving within the same column:
      // removing an earlier card shifts every later card one slot to the left.
      let insertAt =
        source === action.target && sourceIndex < action.targetIndex
          ? action.targetIndex - 1
          : action.targetIndex;
      insertAt = clampIndex(insertAt, withoutCard.length);

      // No-op move (same position): don't announce or touch state identity.
      if (source === action.target && insertAt === sourceIndex) return state;

      const targetCards = [...withoutCard];
      targetCards.splice(insertAt, 0, card);

      return {
        columns: { ...state.columns, [source]: source === action.target ? targetCards : withoutCard, ...(source !== action.target ? { [action.target]: targetCards } : {}) },
        announcements: {
          ...state.announcements,
          [action.target]: `Card ${card.title} moved to ${action.target}`,
        },
      };
    }

    case 'DELETE_CARD': {
      const location = locate(state, action.id);
      if (!location) return state;
      const column = state.columns[location.column].filter((c) => c.id !== action.id);
      return { ...state, columns: { ...state.columns, [location.column]: column } };
    }

    default:
      return state;
  }
}

interface BoardProps {
  initial?: BoardState;
}

export function Board({ initial = initialState() }: BoardProps) {
  const [state, dispatch] = useReducer(boardReducer, initial);

  return (
    <div>
      {COLUMN_IDS.map((col) => (
        <section key={col} aria-label={col}>
          <h2>{col}</h2>
          <p role="status" aria-live="polite">
            {state.announcements[col]}
          </p>
          <ul>
            {state.columns[col].map((card, index) => (
              <li key={card.id} data-card-id={card.id}>
                <h3>{card.title}</h3>
                <button
                  type="button"
                  onClick={() =>
                    dispatch({
                      type: 'MOVE_CARD',
                      id: card.id,
                      target: COLUMN_IDS[COLUMN_IDS.indexOf(col) - 1],
                      targetIndex: state.columns[COLUMN_IDS[COLUMN_IDS.indexOf(col) - 1]].length,
                    })
                  }
                  disabled={index === 0 && col === COLUMN_IDS[0]}
                  hidden={col === COLUMN_IDS[0]}
                >
                  Move left
                </button>
                <button
                  type="button"
                  onClick={() => {
                    const targetCol = COLUMN_IDS[COLUMN_IDS.indexOf(col) + 1];
                    dispatch({
                      type: 'MOVE_CARD',
                      id: card.id,
                      target: targetCol,
                      targetIndex: state.columns[targetCol].length,
                    });
                  }}
                  disabled={col === COLUMN_IDS[COLUMN_IDS.length - 1]}
                >
                  Move right
                </button>
                <button type="button" onClick={() => dispatch({ type: 'DELETE_CARD', id: card.id })}>
                  Delete
                </button>
              </li>
            ))}
          </ul>
        </section>
      ))}
    </div>
  );
}
"})
