result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/kanban/src/Board.test.tsx", "content": "import { describe, expect, it } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Board, initialState, makeCard, type BoardState } from './Board';

function seededState(): BoardState {
  return {
    columns: {
      todo: [makeCard('Write spec'), makeCard('Design API')],
      doing: [makeCard('Implement reducer')],
      done: [],
    },
    announcements: { todo: '', doing: '', done: '' },
  };
}

/** Returns the <li> for a card, found via its heading. */
function getCard(title: string): HTMLElement {
  return screen.getByRole('heading', { name: title }).closest('li') as HTMLElement;
}

function getColumn(heading: string): HTMLElement {
  return screen.getByRole('region', { name: heading });
}

describe('Board rendering', () => {
  it('renders all three columns with their headings', () => {
    render(<Board initial={seededState()} />);
    for (const heading of ['todo', 'doing', 'done']) {
      expect(screen.getByRole('heading', { level: 2, name: heading })).toBeInTheDocument();
    }
    expect(within(getColumn('todo')).getByText('Write spec')).toBeInTheDocument();
    expect(within(getColumn('doing')).getByText('Implement reducer')).toBeInTheDocument();
  });

  it('hides Move left in the leftmost column and disables Move right in the rightmost', () => {
    render(<Board initial={seededState()} />);
    // todo is the left edge: no Move left buttons rendered there at all
    expect(within(getColumn('todo')).queryByRole('button', { name: 'Move left' })).not.toBeInTheDocument();
    // done is empty; put something there first via a fresh render with a done card
    const state = seededState();
    state.columns.done.push(makeCard('Already shipped'));
    const { unmount } = render(<Board initial={state} />);
    const doneCard = screen.getByRole('heading', { name: 'Already shipped' }).closest('li') as HTMLElement;
    expect(within(doneCard).getByRole('button', { name: 'Move right' })).toBeDisabled();
    expect(within(doneCard).getByRole('button', { name: 'Move left' })).toBeEnabled();
    unmount();
  });
});

describe('Board interactions', () => {
  it('clicking Move right moves the card under the correct column heading', async () => {
    const user = userEvent.setup();
    render(<Board initial={seededState()} />);

    await user.click(within(getCard('Write spec')).getByRole('button', { name: 'Move right' }));

    // Card left todo...
    expect(within(getColumn('todo')).queryByText('Write spec')).not.toBeInTheDocument();
    // ...and now sits in doing, appended after its existing card.
    const doingList = within(getColumn('doing')).getByRole('list');
    expect(
      Array.from(doingList.querySelectorAll('h3')).map((h) => h.textContent),
    ).toEqual(['Implement reducer', 'Write spec']);

    // Moving again lands it in done.
    await user.click(within(getCard('Write spec')).getByRole('button', { name: 'Move right' }));
    expect(within(getColumn('done')).getByText('Write spec')).toBeInTheDocument();
    expect(getCard('Write spec').contains(screen.getByRole('button', { name: 'Move right' }))).toBe(true);
    expect(
      within(getCard('Write spec')).getByRole('button', { name: 'Move right' }),
    ).toBeDisabled();
  });

  it('clicking Move left brings the card back', async () => {
    const user = userEvent.setup();
    render(<Board initial={seededState()} />);

    await user.click(within(getCard('Implement reducer')).getByRole('button', { name: 'Move left' }));

    expect(within(getColumn('doing')).queryByText('Implement reducer')).not.toBeInTheDocument();
    const todoList = within(getColumn('todo')).getByRole('list');
    expect(Array.from(todoList.querySelectorAll('h3')).map((h) => h.textContent)).toEqual([
      'Write spec',
      'Design API',
      'Implement reducer',
    ]);
  });

  it('the live region announces the move in the target column', async () => {
    const user = userEvent.setup();
    render(<Board initial={seededState()} />);

    const doingStatus = within(getColumn('doing')).getByRole('status');
    expect(doingStatus).toHaveTextContent('');

    await user.click(within(getCard('Write spec')).getByRole('button', { name: 'Move right' }));
    expect(within(getColumn('doing')).getByRole('status')).toHaveTextContent(
      'Card Write spec moved to doing',
    );

    await user.click(within(getCard('Write spec')).getByRole('button', { name: 'Move right' }));
    expect(within(getColumn('done')).getByRole('status')).toHaveTextContent(
      'Card Write spec moved to done',
    );
    // previous announcement cleared
    expect(within(getColumn('doing')).getByRole('status')).toHaveTextContent('');
  });

  it('Delete removes the card from the board', async () => {
    const user = userEvent.setup();
    render(<Board initial={seededState()} />);

    await user.click(within(getCard('Design API')).getByRole('button', { name: 'Delete' }));

    expect(screen.queryByText('Design API')).not.toBeInTheDocument();
    expect(within(getColumn('todo')).getByText('Write spec')).toBeInTheDocument();
  });
});

describe('initialState sanity', () => {
  it('seeds cards so the board is never empty', () => {
    expect(initialState().columns.todo.length).toBeGreaterThan(0);
  });
});
"})
